    scwin.onpageload = function() {
      dlt_cmnCdP002.setJSON(scwin.jsonP002);
      dlt_cmnCdP003.setJSON(scwin.jsonP003);      
      //sbx_searchCondPicGrpCd.setNodeSet('data:dlt_cmnCdP002','dtlCdNm','dtlCd');
      //sbx_searchCondPicTypeCd.setNodeSet('data:ldt_cmnCdP003_1','dtlCdNm','dtlCd');

      var obj1 = {
          "nodeset" : "data:dlt_cmnCdP002",
          "label" : "dtlCdNm",
          "value" : "dtlCd",
          "height" : 300, 
          "hideHeader" : "true",
          "item" : [{"ref" : "dtlCd", "style" : "width:30%"},{"ref" : "dtlCdNm"}]
      };
      sbx_searchCondPicGrpCd_g.setGridItemset(obj1);

      var obj2 = {
          "nodeset" : "data:ldt_cmnCdP003_1",
          "label" : "dtlCdNm",
          "value" : "dtlCd",
          "height" : 300, 
          "hideHeader" : "true",
